-- VEIL: better starting references for finished items (2026-11-22). Paste into the Supabase SQL Editor and run once;
-- running it again is safe. The first item pictures had the shop's gold frame around them and matched the result screen
-- poorly; these are cut from the shop catalogue the same way as the result screen shows them (IMG_0252-0309).
-- Only the starting references (match_id is null) are replaced; references learned from approved matches stay.
delete from public.icon_refs where kind = 'item' and match_id is null and label in ('magicgun', 'ryujin', 'trident', 'demonfall', 'hunterstrike', 'despair', 'oceanedge', 'windterror', 'endless', 'berserk', 'bloodclaw', 'spiritshout', 'wintercrown', 'fleeting', 'tenku', 'joshou', 'naturalwind', 'nyoibo', 'rustyscythe', 'demonhunt', 'wishlantern', 'oasis', 'genius', 'boltrod', 'bloodwing', 'starscythe', 'heatrod', 'frost', 'concentrated', 'guardianrelic', 'holysword', 'destiny', 'heavenwing', 'talisman', 'radiant', 'punish', 'breastplate', 'immortal', 'dominance', 'valkyrie', 'oracle', 'ancient', 'guardianhelm', 'cursehelm', 'thunderbelt', 'queenswing', 'bladearmor', 'demonboots', 'rapidboots', 'swiftboots', 'arcaneboots', 'magicboots', 'toughboots', 'warriorboots');
insert into public.icon_refs (kind, label, img, status)
